function roleLabels() { return { volunteer:tr("志愿者"), elder:tr("老人"), institution:T('机构','Institution'), admin:tr("管理员") }; }
function navigation() { return [['explore','map',recipient()?T('服务首页','Get help'):tr("发现任务")],['services','calendar',tr("我的服务")],...(state.role==='volunteer'?[['rewards','award',tr("积分与荣誉")]]:[]),['safety','shield',tr("安全中心")],['profile','user',tr("个人资料")],...(state.role==='institution'?[['residents','list',T('批量需求','Batch requests')]]:[]),...(state.role==='admin'?[['admin','settings',tr("管理后台")]]:[])]; }
function save() { try { localStorage.setItem(STORAGE,JSON.stringify(state)); } catch { storageFailed = true; toast(tr("浏览器存储不可用，本次操作仅在当前页面保留。")); } }
function toast(text) { const el = $('#toast'); el.textContent=text; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),4500); }
function date(d) { return new Date(`${d}T12:00:00+08:00`).toLocaleDateString(dateLocale(),{timeZone:'Asia/Singapore',month:'short',day:'numeric',weekday:'short'}); }
function category(t) { const c=CATEGORIES[t.category]; return `<span class="category ${c.color}">${icon(c.icon)}${tr(c.label)}</span>`; }
function btn(text, action, id='', secondary=false, ico='') { return `<button class="btn${secondary?' secondary':''}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${text}</button>`; }
