 ['clock',tr("累计服务时长"),s.hours.toFixed(1),tr("小时"),tr("距离 40h 更近一步")],['heart',tr("已完成服务"),s.sessions,tr("次"),tr("每次陪伴都有意义")],['star',tr("服务平均评分"),s.rating.toFixed(1),'/ 5.0',tr("来自长者的认可")],['gift',tr("我的爱心积分"),state.points,tr("分"),tr("让善意继续传递")]
