function shell(content) { return `<div class="shell"><aside class="sidebar"><a class="brand" href="#explore"><img src="./favicon.svg" alt=""><div><strong>Silver Link</strong><small>${tr("银 龄 连 线")}</small></div></a><div class="nav-label">YOUR COMMUNITY</div><nav class="nav" aria-label="${tr("主导航")}">${navigation().map(([p,i,l])=>`<a href="#${p}" data-page="${p}" class="${page===p?'active':''}"${page===p?' aria-current="page"':''}>${icon(i)}<span>${tr(l)}</span>${p==='services'&&visibleTasks(state).some(t=>['reserved','active'].includes(t.status))?'<b class="badge">1</b>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><span>${icon('leaf')}</span><h3>${recipient()?T("需要帮助，就说出来","A little help is close by"):tr("一点时间，一份温暖")}</h3><p>${recipient()?T("从陪诊到手机教学，社区陪你一起。","From clinic visits to phone lessons, your community is here for you."):tr("你的每一个小时，")+"<br>"+tr("都能点亮一个人的日常。")}</p><button data-action="guide">${tr("了解如何开始")} ${icon('arrow')}</button></div><div class="side-foot">${icon('shield')}<span>${tr("让每一次连接都安心")}</span></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${tr("社区")} ${icon('chevron')} <strong>${navigation().find(n=>n[0]===page)?.[2] || tr("发现任务")}</strong></div><a class="mobile-brand" href="#explore"><img src="./favicon.svg" alt="">Silver Link</a><div class="top-actions">${languageButton()}<span class="demo-label">${tr("交互演示")}</span><button class="icon-button" data-action="text-size" aria-label="${tr("切换大字号")}" title="${tr("切换大字号")}">A<span class="small">a</span></button><select id="role" aria-label="${tr("切换演示角色")}">${Object.entries(roleLabels()).map(([k,v])=>`<option value="${k}"${state.role===k?' selected':''}>${v}${tr("视角")}</option>`).join('')}</select><button class="icon-button notification" data-action="notifications" aria-label="${tr("通知")}">${icon('bell')}</button><div class="user"><span class="avatar">${esc(accountName().slice(0,1))}</span><div><strong>${esc(accountName())}</strong><small>${roleLabels()[state.role]} ${tr("· 演示账户")}</small></div></div></div></header><main class="main" id="main" tabindex="-1">${content}</main></div></div>`; }
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
