 let blocks=''; for(let r=0;r<8;r++) for(let c=0;c<10;c++) { const x=30+c*67+(r%2)*9,y=20+r*65; blocks+=`<rect x="${x}" y="${y}" width="${39+(c%3)*4}" height="${29+(r%3)*5}" rx="${3+c%2}" fill="${(r+c)%4===0?'#e1e6d5':'#e9eade'}" stroke="#dce1d0" stroke-width="1" transform="rotate(-12 ${x} ${y})"/>`; }
