function filteredTasks(){return state.tasks.filter(t=>t.status==='open' && (filter==='all'||t.category===filter)).sort((a,b)=>match(b,state.profile).score-match(a,state.profile).score);}
function taskCard(t){const m=match(t,state.profile);return `<article class="task-card ${selected===t.id?'selected':''}" tabindex="0" role="button" data-action="select-task" data-id="${esc(t.id)}" aria-label="${tr("查看任务：")}${esc(seedText(t,'title'))}"><div class="task-card-top">${category(t)}<span class="match-score">${tr("匹配度")} <b>${m.score}%</b></span></div><h3>${esc(seedText(t,'title'))}</h3>${t.ownerRole==='institution'?`<p class="institution-tag">${T("机构发布","Institution request")} · ${esc(t.institutionTranslations?.[getLanguage()]||autoText(t.institution,getLanguage()))}</p>`:""}<div class="task-meta">${icon('pin')}${esc(t.area)}<span>·</span>${t.distance} km</div><div class="task-meta">${icon('calendar')}${date(t.date)} ${esc(t.time)}<span>·</span>${t.hours} ${tr("小时")}</div><div class="task-bottom"><div class="person"><span class="avatar">${esc(seedText(t,'initials'))}</span>${esc(seedText(t,'elder'))}<span>· ${esc(tr(t.language))}</span></div><span>${m.eligible?tr("适合你的任务"):tr("查看所需条件")} ${icon('chevron')}</span></div></article>`;}
function explorePage(){
 if(recipient())return recipientHome();
 const tasks=filteredTasks(); if(!tasks.some(t=>t.id===selected)) selected=tasks[0]?.id; const t=tasks.find(t=>t.id===selected), m=t?match(t,state.profile):null;
 return heading('SMALL ACTS. STRONGER CONNECTIONS.',`${state.role==='elder'?tr("您好，陈阿姨"):`${tr("你好，")}${esc(field(state.profile,'name'))}`} <span style="color:#b9a06f">☀</span>`,tr("今天，也让一份善意在身边发生。"),btn(tr("发布服务需求"),'create','',false,'plus')) + `<section class="hero"><div class="hero-copy"><span class="pill">${icon('leaf')} ${tr("与社区一起，让陪伴发生")}</span><h2>${tr("你的一点时间，")}<br>${tr("是他们生活里的一束光。")}</h2><p>${tr("从一次陪诊、一堂手机课，到一段散步时光。")}<br>${tr("找到适合你的任务，连接身边需要帮助的人。")}</p><button class="hero-link" data-action="guide">${tr("每一次连接，都有意义")} ${icon('arrow')}</button></div>${heroArt()}</section>`+statCards()+`<section aria-labelledby="explore-heading"><div class="section-heading"><div><h2 id="explore-heading">${tr("发现身边的服务任务")}</h2><p>${tr("根据你的语言、技能和空闲时间，为你找到合适的连接")}</p></div><button class="link-button" data-action="profile-link">${icon('settings')} ${tr("调整匹配偏好")}</button></div><div class="explore ${view==='list'?'list-mode':''}"><div class="explore-toolbar"><div class="filters">${[['all',tr("全部任务"),'map'],...Object.entries(CATEGORIES).map(([k,c])=>[k,c.label,c.icon])].map(([k,l,i])=>`<button class="chip ${filter===k?'active':''}" data-filter="${k}" aria-pressed="${filter===k}">${icon(i)}${tr(l)}</button>`).join('')}</div><div class="view-toggle"><button data-view="map" class="${view==='map'?'active':''}" aria-pressed="${view==='map'}">${icon('map')}${tr("地图")}</button><button data-view="list" class="${view==='list'?'active':''}" aria-pressed="${view==='list'}">${icon('list')}${tr("列表")}</button></div></div><div class="explore-body"><div class="task-list"><div class="list-heading"><span>${tr("找到")} <strong>${tasks.length}</strong> ${tr("个任务")}</span><span>${tr("按匹配度排序 ↓")}</span></div>${tasks.length?tasks.map(taskCard).join(''):`<div class="empty">${tr("暂时没有此类任务")}<br><button class="link-button" data-filter="all">${tr("查看全部任务")}</button></div>`}</div><div class="map-panel"><div class="map-location"><span class="dot"></span>${tr("新加坡 · 中部社区")}</div><div class="map-controls"><button data-action="zoom-in" aria-label="${tr("放大地图")}">${icon('plus')}</button><button data-action="zoom-out" aria-label="${tr("缩小地图")}">${icon('minus')}</button><button data-action="map-reset" aria-label="${tr("重置地图")}">${icon('location')}</button></div><div class="map-art" style="transform:scale(${zoom});transform-origin:50% 40%">${mapSvg()}${tasks.map(q=>`<button class="marker ${CATEGORIES[q.category].color} ${selected===q.id?'selected':''}" style="left:${q.x}%;top:${q.y}%" data-action="map-task" data-id="${esc(q.id)}" aria-label="${esc(seedText(q,'title'))}${tr("，匹配度")} ${match(q,state.profile).score}%">${q.id===selected?`<b class="marker-label">${esc(seedText(q,'elder'))}${tr("需要你的帮助")}</b>`:''}<span>${icon(CATEGORIES[q.category].icon)}</span></button>`).join('')}</div>${t?`<div class="map-summary"><div class="map-summary-top">${icon('spark')} ${tr("为你推荐 ·")} ${m.score}${tr("% 匹配")}</div><h3>${esc(seedText(t,'title'))}</h3><div class="map-summary-row"><p>${m.reasons.slice(0,3).map(reason=>esc(localizeReason(reason))).join(' · ')}<br>${esc(t.area)} · ${t.hours} ${tr("小时的温暖陪伴")}</p>${btn(tr("查看任务"),'detail',t.id,false,'arrow')}</div></div>`:''}<div class="map-caption"><span class="map-key">${tr("仅展示大致服务区域")}</span><span>${tr("社区示意图 · 非实时定位")}</span></div></div></div></div></section><div class="bottom-note"><span>${icon('shield')} ${tr("精确集合点仅在预约确认后展示 · 示例资料均为虚构")}</span><span>Made for a kinder Singapore ♡</span></div>`;
}
function taskActions(t){const r=state.role==='institution'?'elder':state.role;let a='';
 if(r==='volunteer'&&t.status==='applied') a=btn(tr("等待老人确认"),'detail',t.id,true)+btn(tr("撤回申请"),'cancel',t.id,true);
 if(r==='elder'&&t.status==='applied') a=btn(tr("确认预约"),'accept',t.id)+btn(tr("拒绝并重新匹配"),'cancel',t.id,true);
 if(t.status==='reserved') a=(r==='volunteer'?btn(tr("输入签到码，开始服务"),'start',t.id,false,'check'):r==='elder'?`<div class="notice">${tr("一次性签到码：")}<strong style="font-size:20px;letter-spacing:4px">${t.code}</strong><br>${tr("见到志愿者后，将此码告知对方。演示签到不代表身份认证。")}</div>`:'')+(['elder','volunteer'].includes(r)?btn(tr("取消预约"),'cancel',t.id,true):'');
 if(t.status==='active') a=(r==='volunteer'?btn(tr("结束服务并申报时长"),'finish',t.id):'')+btn(tr("安全求助"),'sos',t.id,true,'shield');
 if(t.status==='confirming') a=r==='elder'?btn(`${tr("确认服务时长")} ${t.actualHours} ${tr("小时")}`,'confirm',t.id):`<span class="muted small">${tr("等待老人确认服务时长")}</span>`;
 if(t.status==='completed'&&r==='admin') a=btn(tr("核实服务并发放积分"),'verify',t.id);
 if(['completed','verified'].includes(t.status)&&['elder','volunteer'].includes(r)&&!t[r==='elder'?'elderReview':'volunteerReview']) a+=btn(r==='elder'?tr("评价志愿者"):tr("匿名评价服务体验"),'review',t.id,true,'star');
 return a+btn(tr("任务详情"),'detail',t.id,true);
}
function servicesPage(){if(recipient())return recipientServices();const list=state.tasks.filter(t=>t.status!=='open'&&t.status!=='cancelled'); return heading('EVERY HOUR MATTERS',tr("我的服务"),tr("每一份陪伴，都在这里留下温暖的记录。"),btn(tr("发现新任务"),'explore-link','',false,'map'))+`<div class="notice">${icon('help')} ${tr("演示流程：志愿者申请 → 切换老人视角确认 → 志愿者签到及结束 → 老人确认时长 → 管理员核实。所有角色为本机演示，尚未接入真实账户。")}</div>`+(list.length?list.map(t=>`<article class="service-card"><div class="row spread">${category(t)}<span class="status ${t.status==='active'?'active':''}">${tr(STATUS[t.status])}</span></div><h3>${esc(seedText(t,'title'))}</h3><div class="task-meta">${icon('calendar')}${date(t.date)} ${esc(t.time)} · ${t.actualHours||t.hours} ${tr("小时")} ${icon('pin')}${esc(t.area)} · ${esc(seedText(t,'elder'))}</div>${t.status==='reserved'?`<div class="notice">${tr("已预约。请前往社区公共集合点见面；演示中的集合点为虚构。")}</div>`:''}${t.status==='completed'?`<div class="notice">${tr("双方已确认，等待管理员核实后计入积分及证书。")}</div>`:''}<div class="actions">${taskActions(t)}</div>${t.elderReview?`<div class="review"><span class="rating">${'★'.repeat(t.elderReview.stars)}</span><p>${esc(t.elderReview.text)||tr("谢谢你的陪伴！")}</p><small>${tr("老人对志愿者的评价")}</small></div>`:''}${t.volunteerReview&&state.role!=='elder'?`<div class="review"><span class="rating">${'★'.repeat(t.volunteerReview.stars)}</span><p>${esc(t.volunteerReview.text)}</p><small>${tr("志愿者匿名反馈 · 仅本人及演示管理后台可见")}</small></div>`:''}</article>`).join(''):`<div class="panel empty">${icon('calendar')}<h3>${tr("你的下一段温暖旅程，从这里开始")}</h3><p>${tr("先到地图上，找到一件你愿意帮忙的小事。")}</p><div class="actions" style="justify-content:center">${btn(tr("去发现任务"),'explore-link')}</div></div>`);}
function rewardsPage(){const s=stats(state);return heading('KINDNESS COMES FULL CIRCLE',tr("每一份善意，都值得被看见"),tr("记录你的成长，珍藏每一个温暖的里程碑。"))+statCards()+`<div class="section-heading"><h2>${tr("我的荣誉")}</h2><span class="muted small">${tr("仅经核实服务计入 · 演示门槛")}</span></div><div class="grid-2"><div class="certificate"><div class="medal">${icon('award')}</div><div class="eyebrow">DIGITAL SERVICE CERTIFICATE</div><h3>${tr("社区服务证书")}</h3><p>${tr("累计完成 40 小时经核实的服务")}</p><div class="progress"><span style="width:${Math.min(100,s.hours/40*100)}%"></span></div><p>${s.hours.toFixed(1)} ${tr("/ 40 小时 ·")} ${s.hours>=40?tr("已达到申领条件"):`${tr("还差")} ${(40-s.hours).toFixed(1)} ${tr("小时")}`}</p>${btn(s.hours>=40?tr("下载演示证书"):tr("查看成长进度"),'certificate','service',false,'download')}</div><div class="certificate"><div class="medal" style="background:#e9eddf;color:#91a078">${icon('star')}</div><div class="eyebrow">HONORABLE SERVICE AWARD</div><h3>${tr("卓越服务荣誉勋章")}</h3><p>${tr("100 次好评，且平均评分不低于 4.5")}</p><div class="progress"><span style="width:${Math.min(100,s.positives)}%"></span></div><p>${s.positives} ${tr("/ 100 次好评 · 当前均分")} ${s.rating.toFixed(1)}</p>${btn(certificateEligibility(state,'honor')?tr("下载演示证书"):tr("查看成长进度"),'certificate','honor',true,'award')}</div></div><div class="section-heading" style="margin-top:28px"><div><h2>${tr("让温暖继续传递")}</h2><p>${tr("以下为模拟奖励，尚无合作商兑付；平台积分不是 CDC 积分。")}</p></div></div><div class="grid-3">${[['社区咖啡体验券',150,tr("一杯咖啡，给热心的你。"),'gift'],['社区园艺工作坊',300,tr("把善意种下，和邻里一起发芽。"),'leaf'],['CDC Vouchers 合作探索',0,tr("尚未建立合作，当前无法兑换。"),'bag']].map(([title,cost,desc,i])=>`<article class="reward"><div class="reward-art">${icon(i)}</div><h3>${tr(title)}</h3><p>${desc}</p><footer><strong>${cost?`${cost} ${tr("积分")}`:tr("待正式授权")}</strong>${cost?`<button class="btn secondary" data-action="redeem" data-cost="${cost}" data-title="${title}">${tr("模拟兑换")}</button>`:`<button class="btn secondary" disabled>${tr("暂未开放")}</button>`}</footer></article>`).join('')}</div><div class="panel" style="margin-top:22px"><h2>${tr("积分明细")}</h2><ul class="ledger">${state.ledger.map(l=>`<li><div>${esc(ledgerText(l,state.tasks))}<small>${esc(l.date)}</small></div><strong>${l.amount>0?'+':''}${l.amount} ${tr("分")}</strong></li>`).join('')}</ul></div>`;}
function volunteerProfileSection(){const p=state.profile;return `<section class="panel"><h2>${tr("志愿者资料")}</h2>${translationNotice()}<form id="profile-form"><div class="form-grid">${bilingualInput(p,'name',tr('姓名'),true)}<label class="field wide">${tr("常服务区域")}<select name="area">${['Toa Payoh','Bishan','Ang Mo Kio','Novena','Kallang'].map(a=>`<option ${p.area===a?'selected':''}>${a}</option>`).join('')}</select><small>${tr("区域偏好会保存。地图距离为固定示例数据，尚未接入导航服务。")}</small></label><div class="field wide">${tr("沟通语言")}<div class="checkboxes">${['华语','英语','福建话','马来语','泰米尔语'].map(l=>`<label><input type="checkbox" name="languages" value="${l}" ${p.languages.includes(l)?'checked':''}>${tr(l)}</label>`).join('')}</div></div><div class="field wide">${tr("特长与技能")}<div class="checkboxes">${Object.values(CATEGORIES).map(c=>`<label><input type="checkbox" name="skills" value="${c.label}" ${p.skills.includes(c.label)?'checked':''}>${tr(c.label)}</label>`).join('')}</div></div><div class="field wide">${tr("通常可开始服务的时段")}<div class="checkboxes">${['09:00','10:00','14:00','16:00'].map(l=>`<label><input type="checkbox" name="available" value="${l}" ${p.available.includes(l)?'checked':''}>${tr(l)}</label>`).join('')}</div><small>${tr("当前匹配使用开始时段；完整日期日历待后端接入。")}</small></div>${bilingualInput(p,'interests',tr('兴趣爱好'))}</div><div class="actions"><button class="btn" type="submit">${tr("保存匹配偏好")}</button></div><p class="error" id="profile-error" role="alert"></p></form></section>`;}
function seniorProfileSection(){const e=state.elder;return `<section class="panel"><h2>${tr("老人资料")}</h2>${translationNotice()}<form id="elder-form"><div class="form-grid">${['name','interests','habits','needs'].map((key,i)=>bilingualInput(e,key,[tr('姓名'),tr('兴趣爱好'),tr('生活习惯'),tr('常见需求')][i],i===0)).join('')}<div class="checkboxes">${['华语','英语','福建话','马来语','泰米尔语'].map(l=>`<label><input type="checkbox" name="languages" value="${l}" ${e.languages.includes(l)?'checked':''}>${tr(l)}</label>`).join('')}</div></div><div class="actions"><button type="submit" class="btn">${tr('保存老人资料')}</button></div></form></section>`;}
function profilePage(){if(recipient())return recipientProfile();return heading('A LITTLE ABOUT YOU',tr("让合适的连接，从了解开始"),tr("完善个人资料，让每一次推荐更贴近你的能力与时间。"))+`<div class="grid-2">${state.role==='elder'?seniorProfileSection():volunteerProfileSection()}<div class="stack">${state.role==='admin'?seniorProfileSection():''}<section class="panel"><h3>${tr("你的数据，由你掌握")}</h3><p class="notice">${tr("本演示仅将资料保存在当前浏览器，不会自动上传。请勿输入真实身份证件、住址或敏感资料。")}</p><div class="actions">${btn(tr("导出本机数据"),'export','',true,'download')}${btn(tr("清空并重置演示"),'reset','',true)}</div></section></div></div>`;}
function safetyPage(){return heading('CARE, WITH PEACE OF MIND',tr("每一次陪伴，都多一份安心"),tr("从出发前的确认，到服务中的求助，让彼此都有依靠。"))+`<div class="grid-3"><section class="panel safety-card"><div class="safety-icon">${icon('shield')}</div><h3>${tr("见面确认，更安心")}</h3><p>${tr("预约后生成一次性签到码，见面时由老人提供给志愿者。签到只用于确认演示预约。")}</p><span class="status">${tr("签到码可体验")}</span><p class="small">${tr("Singpass 身份核验：待官方接入，本演示未认证任何真实身份。")}</p></section><section class="panel safety-card"><div class="safety-icon">${icon('mic')}</div><h3>${tr("语音安全辅助")}</h3><p>${tr("实时录音、异常音量与风险词识别尚未接入。未来须在双方明确同意后启用，并提供不录音的替代流程。")}</p><span class="status">${tr("待接入 · 未录音")}</span><p class="small">${tr("本网站不会在服务开始时自动访问麦克风或录音。")}</p></section><section class="panel safety-card sos"><div class="safety-icon">${icon('phone')}</div><h3>${tr("需要帮助时，就在这里")}</h3><p>${tr("查看紧急联系选项并手动拨打电话。当前不支持自动通知、自动呼叫或平台实时值守。")}</p>${btn(tr("打开求助选项"),'sos','',false,'phone')}</section></div><div class="grid-2" style="margin-top:23px"><section class="panel"><h2>${tr("我的紧急联系人")}</h2><form id="contact-form"><div class="form-grid"><label class="field wide">${tr("联系人姓名")}<input name="contactName" value="${esc((recipient()?state.elder:state.profile).contactName||'')}" required maxlength="40" placeholder="${tr("请输入示例联系人")}"></label><label class="field wide">${tr("新加坡联系电话")}<input name="contactPhone" type="tel" pattern="(?:\\+65\\s?)?[689][0-9]{7}" value="${esc((recipient()?state.elder:state.profile).contactPhone||'')}" required placeholder="${tr("例如 +65 81234567")}"><small>${tr("仅本机保存，不会自动发送通知。请先征得联系人同意。")}</small></label></div><div class="actions"><button class="btn" type="submit">${tr("保存联系人")}</button></div></form></section><section class="panel"><h2>${tr("安心服务小贴士")}</h2>${[[tr("第一次见面，在哪里更合适？"),tr("优先在社区中心、公共活动室或其他明亮开放的公共场所会面。出发前核对任务内容与预约时间。")],[tr("服务中感到不舒服怎么办？"),tr("你可以停止服务、离开不安全的环境，并联系紧急联系人。若有紧急危险，请手动拨打 999；医疗急救请拨打 995。")],[tr("如何反馈服务问题？"),tr("任务详情中可提交问题反馈。演示反馈仅保存在当前浏览器，管理后台可查看，不会通知真实工作人员。")]].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></div>`;}
function adminPage(){if(state.role!=='admin') return heading('COMMUNITY OPERATIONS',tr("社区管理后台"),tr("切换到管理员演示视角，查看服务核实和反馈处理。"))+`<div class="panel empty">${icon('shield')}<h3>${tr("管理员演示视角")}</h3><p>${tr("当前页面不会执行管理操作。演示角色切换不代表真实权限认证。")}</p><div class="actions" style="justify-content:center">${btn(tr("进入管理员演示"),'admin-role')}</div></div>`;const pending=state.tasks.filter(t=>t.status==='completed');return heading('COMMUNITY OPERATIONS',tr("社区管理后台"),tr("演示核实、争议处理与操作记录；尚无真实权限认证。"))+appealsAdmin()+`<section class="panel"><h2>${tr("待核实的服务")} <span class="muted small">${pending.length} ${tr("项")}</span></h2>${pending.length?`<div class="table-wrap"><table><thead><tr><th>${tr("服务任务")}</th><th>${tr("双方确认")}</th><th>${tr("申报时长")}</th><th>${tr("操作")}</th></tr></thead><tbody>${pending.map(t=>`<tr><td>${esc(seedText(t,'title'))}</td><td>${tr("已完成")}</td><td>${t.actualHours} ${tr("小时")}</td><td>${btn(tr("核实并发积分"),'verify',t.id)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${tr("暂时没有待核实的服务")}</div>`}</section><div class="grid-2" style="margin-top:22px"><section class="panel"><h2>${tr("服务问题反馈")}</h2>${state.reports.length?state.reports.map(r=>`<div class="review"><span class="status">${r.closed?tr("已处理"):tr("待处理")}</span><h3 style="margin:10px 0">${esc(r.taskTitle)}</h3><p>${esc(r.text)}</p><small>${date(r.date.slice(0,10))} ${tr("· 本机演示反馈")}</small>${!r.closed?`<div class="actions">${btn(tr("标记已处理"),'resolve-report',r.id,true)}</div>`:''}</div>`).join(''):`<div class="empty">${tr("暂无反馈记录")}</div>`}</section><section class="panel"><h2>${tr("最近操作")}</h2>${state.audit.length?state.audit.slice(0,30).map(a=>`<div class="audit-row">${esc(auditText(a,state.tasks))}<small>${new Date(a.date).toLocaleString(dateLocale(),{timeZone:'Asia/Singapore'})} SGT</small></div>`).join(''):`<div class="empty">${tr("服务操作会记录在这里")}</div>`}</section></div>`;}
function certificatePage(){const id=location.hash.split('/')[1];const c=state.certificates.find(c=>c.id===id);return heading('CERTIFICATE CHECK',tr("演示证书核验"),tr("此核验仅适用于当前浏览器的演示数据，不是官方服务证明。"))+`<div class="panel">${c?`<h2>${esc(c.name)} · ${c.kind==='service'?tr("社区服务证书"):tr("卓越服务荣誉")}</h2><p class="notice">${tr("演示编号：")}${esc(c.id)}<br>${tr("生成时间：")}${esc(c.date)}<br>${tr("生成时已核实服务：")}${c.hours} ${tr("小时")}<br>${tr("此本机记录不可作为独立的公开证书验证服务。")}</p>`:`<div class="empty">${tr("当前浏览器中未找到此演示证书。")}</div>`}</div>`;}
function render(){if(!navigation().some(n=>n[0]===page)&&!(page==='certificate'&&state.role==='volunteer'))page='explore';updateDocumentLanguage();const pages={explore:explorePage,services:servicesPage,rewards:rewardsPage,profile:profilePage,safety:safetyPage,admin:adminPage,certificate:certificatePage,residents:institutionPage};$('#app').innerHTML=shell((pages[page]||explorePage)());if(storageFailed) toast(tr("浏览器存储不可用，刷新后可能丢失数据。"));}
function go(p){if(location.hash===`#${p}`){page=p;render();}else location.hash=p;}
function modal(title,body,footer=''){modalErrorKey=null;modalRecipe=currentAction ? { ...currentAction } : null;const d=$('#modal');if(d.open)d.close();d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><div class="modal-head-actions">${languageButton()}<button class="icon-button" data-action="close" aria-label="${tr("关闭对话框")}">${icon('close')}</button></div></div><div class="modal-body">${body}<div id="modal-error" class="error" role="alert"></div></div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;d.showModal();}
function close(){ $('#modal').close(); }
function modalError(e){modalErrorKey=e.message;if($('#modal-error')&&$('#modal').open)$('#modal-error').textContent=tr(e.message);else toast(tr(e.message));}
function detail(id){if(recipient())return recipientDetail(id);currentAction={action:'detail',id};const t=state.tasks.find(t=>t.id===id);if(!t)return;const m=match(t,state.profile);modal(tr("一份小小的帮助"),`${category(t)}<h2 class="detail-title">${esc(seedText(t,'title'))}</h2><div class="task-meta">${icon('calendar')}${date(t.date)} ${esc(t.time)} ${tr("· 预计")} ${t.hours} ${tr("小时")}</div><div class="task-meta">${icon('pin')}${esc(t.area)} · ${t.distance} km · ${esc(tr(t.language))}</div><div class="detail-section"><h3>${tr("需要你做什么")}</h3><div class="detail-copy">${esc(seedText(t,'description'))}</div></div><div class="detail-section"><h3>${tr("关于")}${esc(seedText(t,'elder'))}</h3><p>${t.ownerRole==='institution'?`${T("机构发布","Institution request")}: ${esc(t.institutionTranslations?.[getLanguage()]||autoText(t.institution,getLanguage()))}<br>`:""}${esc(t.age)} ${tr("岁 ·")} ${esc(tr(t.language))} ${tr("沟通 ·")} ${esc(t.area)} ${tr("社区")}</p></div><div class="notice">${icon('spark')} ${tr("匹配度")} ${m.score}% · ${m.reasons.map(reason=>esc(localizeReason(reason))).join(' · ')}${!m.eligible?`<br>${tr("需满足语言、技能和时段条件后才能申请。")}`:''}</div><div class="detail-section"><h3>${tr("服务提醒")}</h3><p>${esc(seedText(t,'note'))}</p></div>${['reserved','active','confirming','completed','verified'].includes(t.status)?`<div class="notice">${tr("演示集合点：")}${esc(t.area)} ${tr("社区中心入口服务台（虚构地点，勿据此前往）。")}<br>${tr("签到不代表 Singpass 身份核验。")}</div>`:`<div class="notice">${tr("精确集合点仅在确认预约后展示，公开地图不展示住宅地址。")}</div>`}${t.status!=='open'?`<p class="muted small">${tr("当前状态：")}${tr(STATUS[t.status])}</p>`:''}`,`${btn(tr("反馈问题"),'report',id,true)}${t.status==='open'&&state.role==='volunteer'?btn(tr("申请帮助这位长者"),'apply',id,false,'heart'):t.status==='open'?`<span class="small muted">${tr("切换志愿者视角即可申请")}</span>`:btn(tr("前往我的服务"),'services-link')}`);}
function createForm(){currentAction={action:'create'};modal(tr("说出需要，让帮助找到你"),`<p>${tr("用自己的话描述就好。系统会用本地关键词规则整理任务草稿，你可以在发布前逐项修改；尚未接入在线 AI。")}</p><form id="request-form"><div class="form-grid"><label class="field wide">${tr("你需要什么帮助？")}<textarea name="description" id="request-text" required minlength="8" maxlength="1000" placeholder="${tr("例如：明天上午想去复诊，希望有一位会说华语的朋友陪我，预计两小时。")}"></textarea></label><div class="wide"><button type="button" class="chip" data-action="dictate">${icon('mic')} ${tr("语音输入（浏览器支持时）")}</button><p id="speech-status" class="muted small" aria-live="polite" style="margin-top:8px"></p></div><label class="field">${tr("服务日期")}<input type="date" name="date" value="${new Date(Date.now()+86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Singapore'})}" min="${new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Singapore'})}" required></label><label class="field">${tr("开始时间")}<input type="time" name="time" value="09:00" required></label><label class="field">${tr("预计时长（小时）")}<input type="number" name="hours" min="0.5" max="8" step="0.5" value="2" required></label><label class="field">${tr("沟通语言")}<select name="language">${['华语','英语','福建话','马来语','泰米尔语'].map(l=>`<option value="${l}">${tr(l)}</option>`).join('')}</select></label><label class="field wide">${tr("大致服务区域")}<select name="area">${['Toa Payoh','Bishan','Ang Mo Kio','Novena','Kallang'].map(a=>`<option>${a}</option>`).join('')}</select></label><label class="field wide"><span><input type="checkbox" name="flexible" style="width:auto;min-height:auto"> ${tr("时间可调整")}</span></label></div><div class="actions"><button class="btn" type="submit">${icon('spark')} ${tr("整理为任务草稿")}</button></div></form>`);}
function draftForm(){currentAction={action:'draft-form'};modal(tr("确认你的任务草稿"),`<div class="notice">${icon('spark')} ${tr("已通过本地规则整理。请检查任务标题、类型、日期和时长，确认后再发布。")}</div><form id="publish-form"><div class="form-grid"><label class="field wide">${tr("任务标题")}<input name="title" value="${esc(draft.title)}" required maxlength="60"></label><label class="field wide">${tr("服务内容")}<textarea name="description" required minlength="8" maxlength="1000">${esc(draft.description)}</textarea></label><label class="field">${tr("服务类型")}<select name="category">${Object.entries(CATEGORIES).map(([k,c])=>`<option value="${k}" ${draft.category===k?'selected':''}>${tr(c.label)}</option>`).join('')}</select></label><label class="field">${tr("预计时长（小时）")}<input name="hours" type="number" min="0.5" max="8" step="0.5" value="${draft.hours}" required></label><label class="field">${tr("日期")}<input name="date" type="date" value="${esc(draft.date)}" required></label><label class="field">${tr("时间")}<input name="time" type="time" value="${esc(draft.time)}" required></label><label class="field wide">${tr("服务注意事项")}<textarea name="note" maxlength="300" placeholder="${tr("如步行速度、无障碍需求，或雨天安排。")}"></textarea></label></div><div class="notice">${esc(draft.area)} · ${esc(tr(draft.language))} · ${draft.flexible?tr("时间可调整"):tr("固定时段")}<br>${tr("任务将以虚构演示身份发布，仅当前浏览器可见，不会联系真实志愿者。")}</div><div class="actions"><button class="btn" type="submit">${tr("确认并发布任务")}</button><button type="button" class="btn secondary" data-action="create">${tr("重新填写")}</button></div></form>`);}
function sos(id){const p=recipient()?state.elder:state.profile;modal(tr("安全求助"),`<div class="notice warning">${tr("本演示不会自动拨号或通知他人，也没有值班人员接收提醒。如有紧急危险，请直接使用下方电话链接或手机拨号。")}</div><h3>${tr("紧急服务 · 新加坡")}</h3><div class="actions"><a class="btn danger" href="tel:999">${tr("警方 999")}</a><a class="btn danger" href="tel:995">${tr("医疗急救 995")}</a></div><div class="detail-section"><h3>${tr("你的紧急联系人")}</h3>${p.contactPhone?`<p>${esc(p.contactName)}</p><div class="actions"><a class="btn secondary" href="tel:${esc(p.contactPhone.replace(/\s/g,''))}">${icon('phone')}${esc(p.contactPhone)}</a></div>`:`<p>${tr("你还没有设置紧急联系人。")}</p><div class="actions">`+btn(tr("设置紧急联系人"),'safety-link','',true)+'</div>'}</div><div class="detail-section"><h3>${tr("服务问题反馈")}</h3><p>${tr("非紧急问题可保存为本机演示反馈，管理后台可查看。")}</p>${id?`<div class="actions">${btn(tr("填写问题反馈"),'report',id,true)}</div>`:''}</div>`);}
function download(filename,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function certificate(kind){currentAction={action:'certificate',id:kind};const s=stats(state);if(!certificateEligibility(state,kind)){modal(tr("你的每一步，都算数"),`<p>${kind==='service'?`${tr("已核实")} ${s.hours.toFixed(1)} ${tr("小时，距离社区服务证书还差")} ${(40-s.hours).toFixed(1)} ${tr("小时。")}`:`${tr("已有")} ${s.positives} ${tr("次好评，需达到 100 次且平均分不低于 4.5。目前均分")} ${s.rating.toFixed(1)}。`}</p><div class="notice">${tr("去找到下一份适合自己的服务，慢慢积累每一次有意义的陪伴。")}</div>`,btn(tr("发现任务"),'explore-link'));return;}
 const c={id:uid('DEMO-CERT'),kind,name:state.profile.name,hours:s.hours,date:new Date().toLocaleDateString(dateLocale(),{timeZone:'Asia/Singapore'})};state.certificates.push(c);save();const url=new URL(location.href);url.hash=`certificate/${c.id}`;
 download(`${c.id}.html`,`<!doctype html><html lang="${getLanguage()==='en'?'en':'zh-Hans'}"><meta charset="UTF-8"><title>${tr("Silver Link 演示证书")}</title><style>body{font-family:system-ui;background:#f7f6ee;color:#315341;padding:8vw;text-align:center}main{border:4px double #c5ad7c;padding:60px;max-width:800px;margin:auto}h1{font-size:36px}p{line-height:2}small{color:#8d9078}</style><main><p>${tr("SILVER LINK · 银龄连线")}</p><h1>${kind==='service'?tr("社区服务证书"):tr("卓越服务荣誉证书")}</h1><h2>${esc(c.name)}</h2><p>${tr("在本机演示中累计完成")} ${c.hours} ${tr("小时已核实的社区服务。")}</p><p>${esc(c.date)}</p><small>${tr("演示编号")} ${esc(c.id)}</small><p><a href="${esc(url.href)}">${tr("当前浏览器演示核验记录")}</a></p><p><strong>${tr("演示样本 · 不具官方效力 · 不可作为真实志愿服务证明")}</strong></p></main></html>`,'text/html');toast(tr("演示证书已生成；核验记录仅保存在当前浏览器。"));}
const actionHandlers={
 'close':close,
 'language':()=>switchLanguage(getLanguage()==='en'?'zh':'en'),
 'draft-form':draftForm,
 'select-task':el=>{selected=el.dataset.id;if(view==='list')detail(selected);else render();},
 'map-task':el=>{selected=el.dataset.id;render();},
 'detail':el=>detail(el.dataset.id),
 'create':()=>{if(state.role==='institution'){close();go('residents');}else createForm();},
 'history':el=>showHistory(el.dataset.id),
 'appeal':el=>appealForm(el.dataset.id),
 'resolve-appeal':el=>resolveAppeal(el.dataset.id),
 'story':el=>{storySelected=el.dataset.id;render();},
 'request-category':el=>{if(state.role==='institution'){go('residents');return;}createForm();$('#request-text').value=serviceDescriptions[el.dataset.id][getLanguage()];},
 'batch-add':()=>{captureBatch();if(batchRows.length>=30)return;batchRows.push({name:'',age:'',language:'华语',category:'companion',description:'',note:''});render();},
 'batch-remove':el=>{captureBatch();batchRows.splice(Number(el.dataset.id),1);render();},
 'batch-preview':()=>previewBatch(),
 'batch-publish':()=>publishBatch(),
 'batch-back':()=>{batchPrepared=[];close();render();},
 'guide':()=>recipient()?recipientGuide():modal(tr("从一件小事开始"),`<div class="stack">${[['1',tr("完善你的资料"),tr("选择你会的语言、擅长的技能和空闲时段。")],['2',tr("找到适合的任务"),tr("浏览地图与推荐原因，了解老人需要什么帮助。")],['3',tr("让陪伴真正发生"),tr("申请后由老人确认预约，见面核对签到码，再开始服务。")],['4',tr("留下温暖的记录"),tr("双方确认时长、评价服务，再由管理员核实计入积分。")]].map(([n,t,p])=>`<div><h3><span class="avatar" style="width:26px;height:26px;margin-right:10px">${n}</span>${t}</h3><p class="muted small" style="margin:8px 0 0 38px;line-height:1.8">${p}</p></div>`).join('')}</div><div class="notice">${tr("当前是本机交互演示：可以在顶部切换三种角色完成整个流程，无真实跨用户通信。")}</div>`,btn(tr("去完善个人资料"),'profile-link')),
 'profile-link':()=>{close();go('profile');},'explore-link':()=>{close();go('explore');},'services-link':()=>{close();go('services');},'safety-link':()=>{close();go('safety');},
 'admin-role':()=>{state.role='admin';save();render();},
 'text-size':()=>{document.body.classList.toggle('large-text');toast(document.body.classList.contains('large-text')?tr("已开启大字号"):tr("已恢复标准字号"));},
 'zoom-in':()=>{zoom=Math.min(1.6,zoom+.2);render();},'zoom-out':()=>{zoom=Math.max(1,zoom-.2);render();},'map-reset':()=>{zoom=1;render();},
 'apply':el=>{transition(state,el.dataset.id,'apply');save();close();go('services');toast(tr("已提交申请。切换老人视角确认预约即可继续演示。"));},
 'accept':el=>{transition(state,el.dataset.id,'accept');save();render();toast(tr("预约已确认，请见面后提供签到码。"));},
 'cancel':el=>modal(tr("取消这次预约？"),`<p>${recipient()?T("取消后将重新寻找帮助，当前签到码失效。","The request will reopen and the current check-in code will expire."):tr("取消后任务会重新开放，当前签到码失效。取消的服务不会计入时长与积分。")}</p>`,btn(tr("保留预约"),'close','',true)+btn(tr("确认取消"),'confirm-cancel',el.dataset.id)),
 'confirm-cancel':el=>{transition(state,el.dataset.id,'cancel');save();close();render();toast(tr("已取消，任务重新开放。"));},
 'start':el=>modal(tr("见面后，核对签到码"),`<p>${tr("请向老人索取预约的六位签到码。演示中可切换老人视角查看，不代表真实身份认证。")}</p><form id="start-form" data-id="${esc(el.dataset.id)}"><label class="field">${tr("六位签到码")}<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"></label><div class="notice">${tr("本次不会开启录音、自动呼叫或实时安全监测。可随时使用安全中心的手动求助入口。")}</div><button type="submit" class="btn">${tr("确认签到，开始服务")}</button></form>`),
 'finish':el=>{const t=state.tasks.find(t=>t.id===el.dataset.id);modal(tr("感谢你，把时间留给了陪伴"),`<p>${tr("填写实际服务时长，交由老人确认，再由管理员核实。本演示允许手动填写时长，不是正式计时凭证。")}</p><form id="finish-form" data-id="${esc(t.id)}"><label class="field">${tr("实际服务时长（小时）")}<input name="hours" type="number" min="0.1" max="12" step="0.1" value="${t.hours}" required></label><div class="actions"><button class="btn" type="submit">${tr("提交时长并签退")}</button></div></form>`);},
 'confirm':el=>{transition(state,el.dataset.id,'confirm');save();render();toast(T('服务时长已确认，谢谢你的反馈。','Service hours confirmed. Thank you.'));},
 'verify':el=>{transition(state,el.dataset.id,'verify');save();render();toast(tr("已核实服务，时长与积分已经更新。"));},
 'review':el=>modal(recipient()?tr("这次陪伴，感觉如何？"):tr("匿名反馈服务体验"),`<p>${recipient()?tr("你的认可，是志愿者继续前行的力量。"):tr("对老人匿名，演示管理员可查看。请专注于服务体验，不填写敏感资料。")}</p><form id="review-form" data-id="${esc(el.dataset.id)}"><div class="field">${tr("服务评分")}<div class="stars" role="radiogroup" aria-label="${tr("服务评分")}">${[1,2,3,4,5].map(i=>`<label><input type="radio" name="stars" value="${i}" ${i===5?'checked':''} required aria-label="${i} ${tr("星")}">${i}★</label>`).join('')}</div></div><label class="field">${tr("评价内容")}<textarea name="text" maxlength="500" placeholder="${tr("分享让你印象深刻的小事……")}"></textarea></label><div class="actions"><button class="btn" type="submit">${tr("提交评价")}</button></div></form>`),
 'sos':el=>sos(el.dataset.id),
 'report':el=>modal(tr("记录服务问题"),`<p>${tr("反馈仅保存在当前浏览器，由演示管理后台查看，不会通知真实工作人员。紧急情况请直接求助。")}</p><form id="report-form" data-id="${esc(el.dataset.id)}"><label class="field">${tr("遇到了什么问题？")}<textarea name="text" required minlength="5" maxlength="1000" placeholder="${tr("请描述情况，不要填写敏感个人信息。")}"></textarea></label><div class="actions"><button class="btn" type="submit">${tr("保存演示反馈")}</button></div></form>`),
 'resolve-report':el=>{if(state.role!=='admin')throw new Error(tr("请切换管理员演示视角。"));const r=state.reports.find(r=>r.id===el.dataset.id);r.closed=true;audit(state,`反馈已处理 · ${r.taskTitle}`,{type:'resolved',taskId:r.taskId});save();render();toast(tr("已标记为处理完成。"));},
 'certificate':el=>certificate(el.dataset.id),
 'redeem':el=>modal(tr("模拟兑换确认"),`<p>${tr("使用")} ${el.dataset.cost} ${tr("积分兑换「")}${esc(tr(el.dataset.title))}${tr("」演示奖励？")}</p><div class="notice warning">${tr("这只是交互演示，不生成真实优惠券，也无法向商家兑付。")}</div>`,btn(tr("取消"),'close','',true)+`<button class="btn" data-action="confirm-redeem" data-cost="${el.dataset.cost}" data-title="${esc(el.dataset.title)}">${tr("确认模拟兑换")}</button>`),
 'confirm-redeem':el=>{redeem(state,Number(el.dataset.cost),el.dataset.title);save();close();render();toast(tr("模拟兑换完成，积分明细已更新；不产生真实优惠券。"));},
 'export':()=>download('silverlink-demo-data.json',JSON.stringify(state,null,2),'application/json'),
 'reset':()=>modal(tr("清空本机演示数据？"),`<p>${tr("将删除你在此浏览器填写的资料、任务、评价和演示证书，恢复最初的虚构示例。此操作无法撤销。")}</p>`,btn(tr("保留数据"),'close','',true)+btn(tr("清空并恢复示例"),'confirm-reset')),
 'confirm-reset':()=>{state=initialState();state.appeals=[];state.institution={name:'银龄社区养老院'};save();close();render();toast(tr("已恢复初始示例数据。"));},
 'notifications':()=>modal(tr("你的社区动态"),`<p>${tr("你有")} ${visibleTasks(state).filter(t=>['applied','reserved','confirming','completed'].includes(t.status)).length} ${tr("条需要跟进的服务记录。")}</p><div class="notice">${tr("通知来自当前浏览器的演示状态，未接入推送或短信。")}</div>`,btn(tr("查看我的服务"),'services-link')),
 'dictate':()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast(tr("此浏览器不支持语音输入，请直接输入文字。"));return;}modal(tr("使用浏览器语音输入？"),`<p>${tr("开始后浏览器会请求麦克风权限。语音识别可能由浏览器提供商处理；本网站不保存录音。若不希望使用语音，可继续文字输入。")}</p>`,btn(tr("继续文字输入"),'create','',true)+btn(tr("同意并开始"),'start-dictate'));},
 'start-dictate':()=>{createForm();const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;const recognition=new Speech();recognition.lang=dateLocale();recognition.interimResults=false;$('#speech-status').textContent=tr("正在聆听，请描述你的需求……");recognition.onresult=e=>{if($('#request-text'))$('#request-text').value=e.results[0][0].transcript;if($('#speech-status'))$('#speech-status').textContent=tr("语音已转换，请检查文字。");};recognition.onerror=()=>{if($('#speech-status'))$('#speech-status').textContent=tr("语音输入不可用，请改用文字。");};recognition.onend=()=>{if($('#speech-status')?.textContent===tr("正在聆听，请描述你的需求……"))$('#speech-status').textContent=tr("聆听已结束。");};recognition.start();$('#modal').addEventListener('close',()=>recognition.abort(),{once:true});},
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-filter],[data-view]');if(!el)return;try{if(el.dataset.filter){filter=el.dataset.filter;render();}else if(el.dataset.view){view=el.dataset.view;render();}else { currentAction={...el.dataset}; actionHandlers[el.dataset.action]?.(el); }}catch(err){modalError(err);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[role="button"]')){e.preventDefault();e.target.click();}});
document.addEventListener('change',e=>{if(e.target.id==='role'){close();state.role=e.target.value;filter='all';save();render();toast(`${tr("已切换到")}${roleLabels()[state.role]}${tr("演示视角")}`);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),id=form.dataset.id;try{
 if(form.id==='appeal-form'){submitAppeal(fd);return;}
 if(form.id==='institution-form'){saveProfileFields(state.institution,fd,['name']);save();render();toast(T('机构资料已保存。','Institution profile saved.'));return;}
 if(form.id==='batch-form'){previewBatch();return;}
 if(form.id==='request-form'){if(new Date(`${fd.get('date')}T23:59:59+08:00`) < new Date())throw new Error(tr("请选择今天或之后的服务日期。"));draft=parseRequest(fd.get('description'),{date:fd.get('date'),time:fd.get('time'),hours:Number(fd.get('hours')),language:fd.get('language'),area:fd.get('area'),flexible:fd.has('flexible')});draftForm();}
 if(form.id==='publish-form'){if(new Date(`${fd.get('date')}T${fd.get('time')}:00+08:00`) < new Date())throw new Error(tr("服务开始时间已过去，请调整。"));const coords={'Toa Payoh':[45,40,.9],Bishan:[60,22,2],'Ang Mo Kio':[75,33,3.5],Novena:[29,65,2.8],Kallang:[76,72,4.2]},[x,y,distance]=coords[draft.area];const t={...draft,id:uid('SL'),title:fd.get('title').trim(),description:fd.get('description').trim(),category:fd.get('category'),date:fd.get('date'),time:fd.get('time'),hours:Number(fd.get('hours')),note:fd.get('note').trim()||tr("见面前请确认服务内容与集合地点。"),elder:state.elder.name,ownerRole:state.role==='institution'?'institution':'elder',institution:state.role==='institution'?state.institution.name:undefined,age:72,initials:state.elder.name.slice(0,1),x,y,distance,status:'open'};state.tasks.unshift(t);audit(state,`发布演示任务 · ${t.title}`,{type:'published',taskId:t.id});save();selected=t.id;filter='all';draft=null;close();go('explore');toast(tr("任务已发布到本机演示地图。"));}
 if(form.id==='profile-form'){saveProfileFields(state.profile,fd,['name','interests']);const languages=fd.getAll('languages'),skills=fd.getAll('skills'),available=fd.getAll('available');if(!languages.length||!skills.length||!available.length)throw new Error(tr("请至少选择一种语言、一项技能与一个空闲时段。"));state.profile={...state.profile,area:fd.get('area'),languages,skills,available};save();render();toast(tr("个人资料已保存，任务推荐已更新。"));}
 if(form.id==='elder-form'){saveProfileFields(state.elder,fd,['name','interests','habits','needs']);state.elder.languages=fd.getAll('languages');if(!state.elder.languages.length)throw new Error(T('请至少选择一种沟通语言。','Please select at least one language.'));save();render();toast(tr("老人资料已保存。"));}
 if(form.id==='contact-form'){const contact=recipient()?state.elder:state.profile;contact.contactName=fd.get('contactName').trim();contact.contactPhone=fd.get('contactPhone').trim();save();toast(tr("紧急联系人已保存到当前浏览器。"));}
 if(form.id==='start-form'){transition(state,id,'start',{code:fd.get('code')});save();close();render();toast(tr("服务已开始。安全中心可随时手动求助。"));}
 if(form.id==='finish-form'){transition(state,id,'finish',{hours:fd.get('hours')});save();close();render();toast(tr("已签退，等待老人确认实际时长。"));}
 if(form.id==='review-form'){transition(state,id,'review',{stars:fd.get('stars'),text:fd.get('text')});save();close();render();toast(tr("评价已保存，感谢你的反馈。"));}
 if(form.id==='report-form'){const t=state.tasks.find(t=>t.id===id);state.reports.unshift({id:uid('report'),taskId:id,taskTitle:t.title,text:fd.get('text').trim(),date:new Date().toISOString(),closed:false});audit(state,`收到演示反馈 · ${t.title}`,{type:'report',taskId:id});save();close();render();toast(tr("已保存本机演示反馈，不会发送通知。"));}
 }catch(err){if(form.id==='profile-form')$('#profile-error').textContent=tr(err.message);else modalError(err);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1).split('/')[0]||'explore';close();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===LANGUAGE_STORAGE_KEY && ['zh','en'].includes(e.newValue)) switchLanguage(e.newValue,{persist:false,notify:false});if(e.key===STORAGE){try{const v=JSON.parse(e.newValue);if(v?.version===1){state=v;state.appeals??=[];state.institution??={name:'银龄社区养老院'};render();toast(tr("已更新同一浏览器其他标签页的演示数据。"));}}catch{}}});
function languageButton() {
  const english=getLanguage()==='en';
  return `<button class="language-switch" data-action="language" aria-label="${tr(english?'切换到中文':'切换到英文')}" lang="${english?'zh-Hans':'en'}" title="${tr(english?'切换到中文':'切换到英文')}">${english?'中文':'EN'}</button>`;
}
function updateDocumentLanguage() {
  const english=getLanguage()==='en';
  document.documentElement.lang=english?'en':'zh-Hans';
  document.documentElement.dataset.language=getLanguage();
  document.title=tr('Silver Link 银龄连线 · 让善意，就在身边');
  document.querySelector('meta[name="description"]').content=tr('银龄连线：连接新加坡长者与社区志愿者，让身边的善意发生。');
  document.querySelector('.skip').textContent=tr('跳到主要内容');
}
function captureForms() {
  return [...document.querySelectorAll('form')].map(form=>({id:form.id,controls:[...form.elements].filter(el=>el.name).map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked}))}));
}
function restoreForms(forms) {
  for (const snapshot of forms) {
    const form=document.getElementById(snapshot.id);
    if(!form)continue;
    for(const item of snapshot.controls) {
      const el=[...form.elements].find(el=>el.name===item.name&&(!['checkbox','radio'].includes(item.type)||el.value===item.value));
      if(!el)continue;
      if(['checkbox','radio'].includes(item.type))el.checked=item.checked;
      else el.value=item.value;
    }
  }
}
function switchLanguage(next,options={}) {
  const previousLanguage=getLanguage();captureProfileDrafts();if(page==='residents')captureBatch();const forms=captureForms(), wasOpen=$('#modal').open, recipe=modalRecipe, errorKey=modalErrorKey;
  const scroll=window.scrollY, modalScroll=$('#modal').scrollTop;
  setLanguage(next,options);
  render();
  if(wasOpen&&recipe) {
    currentAction={...recipe};
    actionHandlers[recipe.action]?.({dataset:recipe});
    if(errorKey) { modalErrorKey=errorKey; $('#modal-error').textContent=tr(errorKey); }
  }
  restoreForms(forms.filter(f=>!['profile-form','elder-form','institution-form','batch-form'].includes(f.id)));
  translateVisibleFields(previousLanguage,next);
  window.scrollTo(0,scroll);
  if(wasOpen)$('#modal').scrollTop=modalScroll;
  (wasOpen?$('#modal'):document).querySelector('[data-action="language"]')?.focus({preventScroll:true});
  if(options.notify!==false)toast(tr('语言已切换为中文'));
}
// Match validation to the selected UI language rather than the browser's installation language.
document.addEventListener('invalid',event=>{
  const input=event.target;
  if(!input.setCustomValidity)return;
  input.setCustomValidity('');
  const v=input.validity;
  const key=v.valueMissing?'请选择填写此项。':v.patternMismatch?'请使用指定格式。':v.tooShort?'输入内容过短。':(v.rangeOverflow||v.rangeUnderflow)?'请输入有效范围内的数值。':v.stepMismatch?'请输入符合步长的数值。':'请输入有效值。';
  input.setCustomValidity(tr(key));
},true);
document.addEventListener('input',event=>event.target.setCustomValidity?.(''));
document.addEventListener('change',event=>event.target.setCustomValidity?.(''));

