function recipientDetail(id){const t=visibleTasks(state).find(t=>t.id===id);if(!t)return;currentAction={action:'detail',id};modal(T('您的服务安排','Your service arrangement'),`${category(t)}<h2 class="detail-title">${esc(seedText(t,'title'))}</h2><p>${date(t.date)} · ${t.time} · ${t.hours} ${tr('小时')} · ${esc(t.area)}</p><div class="detail-copy">${esc(seedText(t,'description'))}</div><p class="notice">${esc(seedText(t,'note'))}</p><p>${tr(STATUS[t.status])}</p>`,btn(tr('反馈问题'),'report',id,true)+btn(tr('前往我的服务'),'services-link'));}
function translationNotice(){return `<p class="notice">${T('资料随语言切换显示，原文会保留。常用表达自动转换；若浏览器支持本机翻译，可转换更多内容。姓名与未识别内容可展开下方字段校对另一种语言。','Profiles follow your language choice and keep the original. Common phrases translate automatically; supported browsers can translate more text locally. Expand each field to review names or other untranslated content.')}</p>`;}
function bilingualInput(record,key,label,required=false){const lang=getLanguage(),other=lang==='zh'?'en':'zh',value=field(record,key),alt=localizedField(record,key,other);const needsReview=alt===value&&value&&!/^\d+$/.test(value);return `<div class="field wide"><label>${label}<input name="${key}" value="${esc(value)}" ${required?'required':''} maxlength="${key==='name'?60:300}" data-bilingual="${key}"></label><details class="translation-detail"><summary>${T('校对英文版本','Review Chinese version')}${needsReview?' · '+T('待校对','Review needed'):''}</summary><input name="${key}__${other}" value="${esc(alt)}" maxlength="300" aria-label="${label} · ${other==='en'?'English':'中文'}"><small>${T('姓名可填写常用英文名或拼音；不会擅自更改身份。','Use a preferred name or transliteration; names are never guessed.')}</small></details></div>`;}
function saveProfileFields(record,fd,keys){for(const key of keys){const lang=getLanguage(),other=lang==='zh'?'en':'zh',oldAlt=localizedField(record,key,other),newAlt=fd.get(key+'__'+other);saveLocalized(record,key,fd.get(key),lang);if(newAlt!==null&&newAlt.trim()&&newAlt!==oldAlt)record.translations[key][other]=newAlt.trim();}}
function captureProfileDrafts(){for(const [id,record,keys] of [['profile-form',state.profile,['name','interests']],['elder-form',state.elder,['name','interests','habits','needs']],['institution-form',state.institution,['name']]]){const form=document.getElementById(id);if(form){const fd=new FormData(form);saveProfileFields(record,fd,keys);if(id==='profile-form'){record.languages=fd.getAll('languages');record.skills=fd.getAll('skills');record.available=fd.getAll('available');record.area=fd.get('area');}if(id==='elder-form')record.languages=fd.getAll('languages');}}}
async function translateVisibleFields(from,to){if(!globalThis.Translator||from===to)return;const sourceLanguage=from==='zh'?'zh':'en',targetLanguage=to==='zh'?'zh':'en';try{const available=await globalThis.Translator.availability({sourceLanguage,targetLanguage});if(available==='unavailable')return;const translator=await globalThis.Translator.create({sourceLanguage,targetLanguage});for(const el of document.querySelectorAll('[data-bilingual]')){if(el.name==='name'||!el.value||(/\p{Script=Han}/u.test(el.value)===(to==='zh')))continue;const old=el.value;const translated=await translator.translate(old);if(el.isConnected&&el.value===old&&getLanguage()===to){el.value=translated;const record=el.form?.id==='elder-form'?state.elder:el.form?.id==='institution-form'?state.institution:state.profile;record.translations??={};record.translations[el.name]??={};record.translations[el.name][from]??=old;record.translations[el.name][to]=translated;}}translator.destroy();}catch{/* Keep the original and editable bilingual version when local translation is unavailable. */}}
function recipientProfile(){const record=state.role==='institution'?state.institution:state.elder;return heading('A LITTLE ABOUT YOU',state.role==='institution'?T('机构资料','Institution profile'):tr('老人资料'),T('填写您的偏好，让帮助更贴心。','Tell us your preferences so help feels right.'))+`<div class="grid-2"><section class="panel">${translationNotice()}<form id="${state.role==='institution'?'institution-form':'elder-form'}"><div class="form-grid">${bilingualInput(record,'name',state.role==='institution'?T('机构名称','Institution name'):tr('姓名'),true)}${state.role==='elder'?`<div class="field wide">${tr('沟通语言')}<div class="checkboxes">${['华语','英语','福建话','马来语','泰米尔语'].map(l=>`<label><input type="checkbox" name="languages" value="${l}" ${record.languages.includes(l)?'checked':''}>${tr(l)}</label>`).join('')}</div></div>${bilingualInput(record,'interests',tr('兴趣爱好'))}${bilingualInput(record,'habits',tr('生活习惯'))}${bilingualInput(record,'needs',tr('常见需求'))}`:''}</div><div class="actions"><button class="btn" type="submit">${T('保存资料','Save profile')}</button></div></form></section><section class="panel"><h2>${T('您的资料，由您掌握','Your information, your choice')}</h2><p class="notice">${tr('本演示仅将资料保存在当前浏览器，不会自动上传。请勿输入真实身份证件、住址或敏感资料。')}</p>${state.role==='institution'?`<a class="btn" href="#residents">${T('批量填写老人信息','Add residents in a batch')}</a>`:''}<div class="actions">${btn(tr('导出本机数据'),'export','',true)}${btn(tr('清空并重置演示'),'reset','',true)}</div></section></div>`;}
function showHistory(tab='hours'){if(state.role!=='volunteer')return;historyTab=tab;currentAction={action:'history',id:tab};const records=historyRecords(state);const tabs={hours:T('服务时长','Hours'),sessions:T('完成次数','Visits'),rating:T('服务评分','Ratings'),points:T('积分明细','Points')};modal(T('每一份陪伴，都有记录','Every visit has a record'),`<div class="history-tabs">${Object.entries(tabs).map(([k,v])=>`<button class="chip ${tab===k?'active':''}" data-action="history" data-id="${k}" aria-pressed="${tab===k}">${v}</button>`).join('')}</div><p class="notice">${T('以下 18 条历史记录为虚构示例，与首页的 36 小时、18 次服务、360 积分对应。新核实服务会自动加入。','The 18 fictional historical records account for the initial 36 hours, 18 visits and 360 points. Newly verified services are added automatically.')}</p><div class="history-list">${records.map(r=>`<article class="history-record"><div class="row spread"><strong>${tr(CATEGORIES[r.category].label)}</strong><span class="status">${T('已核实','Verified')}</span></div><p>${r.date} · ${esc(autoText(r.elder,getLanguage()))}</p><small>${esc(r.id)}</small><div class="record-metrics"><span class="${tab==='hours'?'emphasis':''}">${r.hours} ${tr('小时')}</span><span class="${tab==='points'?'emphasis':''}">+${r.points} ${tr('积分')}</span><span class="${tab==='rating'?'emphasis':''}">${r.rating===null?T('待评价','Not yet rated'):r.rating+' / 5 ★'}</span></div>${btn(T('记录有误？申诉','Something missing? Appeal'),'appeal',r.id,true)}</article>`).join('')}</div>${tab==='points'?`<h3>${T('积分余额与兑换','Balance and redemptions')}: ${state.points}</h3><ul class="ledger">${state.ledger.filter(l=>l.amount<0).map(l=>`<li>${esc(ledgerText(l,state.tasks))}<strong>${l.amount}</strong></li>`).join('')||`<li>${T('暂无兑换','No redemptions yet')}</li>`}</ul>`:''}<h3>${T('我的申诉','My appeals')}</h3>${state.appeals.map(a=>`<div class="review"><span class="status">${a.status==='resolved'?T('已处理','Resolved'):T('待核查','Awaiting review')}</span><p>${esc(a.id)} · ${esc(a.recordId||T('缺失记录','Missing record'))}</p><p>${esc(a.details)}</p>${a.resolution?`<p>${T('后台回复：','Admin response: ')}${esc(a.resolution)}</p>`:''}</div>`).join('')||`<p class="notice">${T('暂无申诉','No appeals yet')}</p>`}`,btn(T('申诉缺失的服务记录','Report a missing service'),'appeal','missing',true));}
function appealForm(id){if(state.role!=='volunteer')return;currentAction={action:'appeal',id};modal(T('服务记录申诉','Service record appeal'),`<p>${T('说明缺漏的时长、积分或服务记录。演示申诉进入本浏览器管理后台，不会通知真实工作人员。','Describe missing hours, points or a service. Demo appeals go to this browser’s admin view; no real staff are notified.')}</p><form id="appeal-form"><div class="form-grid"><label class="field wide">${T('记录编号','Record ID')}<input name="recordId" value="${id==='missing'?'':esc(id)}" maxlength="100" placeholder="${T('缺失记录可留空','Leave blank for a missing service')}"></label><label class="field">${T('服务日期','Service date')}<input type="date" name="date" required></label><label class="field">${T('问题类型','Issue type')}<select name="kind"><option value="missing">${T('缺失记录','Missing service')}</option><option value="hours">${T('时长有误','Incorrect hours')}</option><option value="points">${T('积分有误','Incorrect points')}</option><option value="rating">${T('评分有误','Incorrect rating')}</option></select></label><label class="field">${T('应计时长（可选）','Expected hours (optional)')}<input name="hours" type="number" min="0.1" max="12" step="0.1"></label><label class="field">${T('应得积分（可选）','Expected points (optional)')}<input name="points" type="number" min="0" max="120" step="1"></label><label class="field wide">${T('情况说明与核对依据','Details and verification information')}<textarea name="details" required minlength="5" maxlength="1000"></textarea></label></div><div class="actions"><button type="submit" class="btn">${T('提交演示申诉','Submit demo appeal')}</button></div></form>`);}
function submitAppeal(fd){if(state.role!=='volunteer')return;state.appeals.unshift({id:uid('APPEAL'),recordId:fd.get('recordId').trim(),serviceDate:fd.get('date'),kind:fd.get('kind'),hours:fd.get('hours'),points:fd.get('points'),details:fd.get('details').trim(),status:'pending',createdAt:new Date().toISOString()});save();showHistory(historyTab);toast(T('申诉已登记，可在管理后台核查。','Appeal saved for review in the demo admin view.'));}
function appealsAdmin(){return `<section class="panel appeals-panel"><h2>${T('服务记录申诉','Service record appeals')} · ${state.appeals.filter(a=>a.status==='pending').length}</h2>${state.appeals.map(a=>`<article class="review"><div class="row spread"><strong>${esc(a.recordId||T('缺失记录','Missing service'))}</strong><span class="status">${a.status==='resolved'?T('已处理','Resolved'):T('待核查','Pending')}</span></div><p>${a.serviceDate} · ${esc(({missing:T('缺失记录','Missing service'),hours:T('时长','Hours'),points:T('积分','Points'),rating:T('评分','Rating')})[a.kind]||a.kind)} · ${esc(a.hours||'—')} h · ${esc(a.points||'—')} ${tr('积分')}</p><p>${esc(a.details)}</p>${a.status==='pending'?`<label class="field">${T('核查结果（不会自动改动积分）','Review outcome (does not automatically change points)')}<textarea id="resolution-${esc(a.id)}" maxlength="500"></textarea></label><div class="actions">${btn(T('回复并结案','Reply and resolve'),'resolve-appeal',a.id)}</div>`:`<p>${esc(a.resolution)}</p>`}</article>`).join('')||`<p class="muted">${T('暂无申诉','No appeals yet')}</p>`}</section>`;}
function resolveAppeal(id){if(state.role!=='admin')return;const a=state.appeals.find(a=>a.id===id),text=document.getElementById('resolution-'+id)?.value.trim();if(!text)throw new Error(T('请填写核查结果。','Please enter a review outcome.'));a.status='resolved';a.resolution=text;a.resolvedAt=new Date().toISOString();save();render();toast(T('申诉已回复，可在志愿者记录中查看。','Reply saved and visible in the volunteer’s history.'));}
let batchCommon={date:new Date(Date.now()+86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Singapore'}),time:'09:00',hours:2,area:'Toa Payoh'},batchPrepared=[];
function captureBatch(){const f=document.getElementById('batch-form');if(!f)return;const fd=new FormData(f);batchCommon={date:fd.get('date'),time:fd.get('time'),hours:Number(fd.get('hours')),area:fd.get('area'),consent:fd.has('consent')};batchRows=[...f.querySelectorAll('[data-resident]')].map(row=>Object.fromEntries(['name','age','language','category','description','note'].map(key=>[key,row.querySelector(`[data-key="${key}"]`).value])));}
function institutionPage(){if(state.role!=='institution')return recipientHome();batchRows??=[{name:'',age:'',language:'华语',category:'medical',description:'',note:''}];return heading('CARE FOR EVERY RESIDENT',T('一次填写，照顾更多老人','One batch, care for more residents'),T('每位老人单独生成服务需求，按语言、技能和时间匹配。','Each resident gets an individual request, matched by language, skills and time.'))+`<section class="panel"><form id="batch-form"><h2>${T('共同服务安排','Shared arrangements')}</h2><div class="form-grid"><label class="field">${tr('服务日期')}<input name="date" type="date" value="${batchCommon.date}" required></label><label class="field">${tr('开始时间')}<input name="time" type="time" value="${batchCommon.time}" required></label><label class="field">${tr('预计时长（小时）')}<input name="hours" type="number" min="0.5" max="8" step="0.5" value="${batchCommon.hours}" required></label><label class="field">${tr('大致服务区域')}<select name="area">${['Toa Payoh','Bishan','Ang Mo Kio','Novena','Kallang'].map(a=>`<option ${batchCommon.area===a?'selected':''}>${a}</option>`).join('')}</select></label></div><p class="notice">${T('最多一次录入 30 位老人。请仅使用示例称呼，不填写真实住址或医疗资料。每个需求独立预约，同一志愿者不能承接时间重叠的服务。','Add up to 30 residents at once. Use demo names, without real addresses or medical details. Each request is booked separately; overlapping bookings are not allowed.')}</p><div class="resident-list">${batchRows.map((r,i)=>`<fieldset class="resident-row" data-resident="${i}"><legend>${T('老人','Resident')} ${i+1}</legend><div class="form-grid"><label class="field">${T('称呼','Preferred name')}<input data-key="name" value="${esc(autoText(r.name,getLanguage()))}" required maxlength="60"></label><label class="field">${T('年龄','Age')}<input data-key="age" type="number" min="55" max="120" step="1" value="${esc(r.age)}" required></label><label class="field">${tr('沟通语言')}<select data-key="language">${['华语','英语','福建话','马来语','泰米尔语'].map(l=>`<option value="${l}" ${r.language===l?'selected':''}>${tr(l)}</option>`).join('')}</select></label><label class="field">${tr('服务类型')}<select data-key="category">${Object.entries(CATEGORIES).map(([key,c])=>`<option value="${key}" ${r.category===key?'selected':''}>${tr(c.label)}</option>`).join('')}</select></label><label class="field wide">${tr('服务内容')}<textarea data-key="description" required minlength="5" maxlength="500">${esc(autoText(r.description,getLanguage()))}</textarea></label><label class="field wide">${tr('服务注意事项')}<input data-key="note" value="${esc(autoText(r.note,getLanguage()))}" maxlength="300" placeholder="${T('例如：步行较慢，需要耐心陪伴','For example: walks slowly; patient support needed')}"></label></div>${batchRows.length>1?`<button type="button" class="link-button" data-action="batch-remove" data-id="${i}">${T('移除此行','Remove resident')}</button>`:''}</fieldset>`).join('')}</div><div class="actions"><button class="btn secondary" type="button" data-action="batch-add" ${batchRows.length>=30?'disabled':''}>${icon('plus')}${T('添加一位老人','Add a resident')}</button><button class="btn" type="submit">${T('预览并检查','Preview and check')} (${batchRows.length})</button></div><label class="batch-consent"><input type="checkbox" name="consent" ${batchCommon.consent?'checked':''} required> ${T('我确认有权代表这些老人提出服务申请，已向他们说明使用范围。','I am authorised to submit these requests and have explained their intended use to the residents.')}</label></form></section>`;}
function previewBatch(){if(state.role!=='institution')return;if($('#modal').open&&batchPrepared.length){showBatchPreview();return;}const f=document.getElementById('batch-form');if(!f?.reportValidity())return;captureBatch();if(new Date(`${batchCommon.date}T${batchCommon.time}:00+08:00`)<=new Date())throw new Error(T('请选择未来的服务时间。','Choose a future service time.'));batchPrepared=batchTasks(batchRows,{...batchCommon,institution:state.institution.name,institutionTranslations:state.institution.translations?.name},()=>uid('SL'));showBatchPreview();}
function showBatchPreview(){currentAction={action:'batch-preview'};modal(T('确认批量服务需求','Confirm batch requests'),`<p>${T('发布后，每位老人会显示为独立任务，志愿者可以按自己的能力选择。','After publishing, each resident appears as a separate task so volunteers can choose according to their abilities.')}</p><div class="stack">${batchPrepared.map(t=>`<article class="review">${category(t)}<h3>${esc(autoText(t.elder,getLanguage()))} · ${t.age}</h3><p>${esc(autoText(t.description,getLanguage()))}</p><p>${tr(t.language)} · ${t.date} ${t.time} · ${t.hours} h · ${esc(t.area)}</p><p>${esc(t.note)}</p></article>`).join('')}</div>`,btn(T('返回修改','Back to edit'),'batch-back','',true)+btn(T('确认发布全部需求','Publish all requests'),'batch-publish'));}
function publishBatch(){if(state.role!=='institution'||!batchPrepared.length)return;state.tasks.unshift(...batchPrepared);audit(state,T(`机构批量发布 ${batchPrepared.length} 条需求`,`Institution published ${batchPrepared.length} requests`));save();const count=batchPrepared.length;batchPrepared=[];batchRows=null;close();go('services');toast(T(`已发布 ${count} 条独立服务需求。`,`Published ${count} individual requests.`));}

render();
